INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(127070, 'ruRU', '', 'Похоже, дредлорды Легиона нашли способ создавать агентов-нежить настолько живоподобных, что даже мне трудно их обнаружить!', 24330),
(127071, 'ruRU', '', 'Демоны знали, что иллидари найдут их, если они снова попытаются проникнуть в наши города, поэтому они послали этих... гомункулов.', 24330),
(127072, 'ruRU', '', 'Наши агенты выявили предполагаемых гомункулов в Луносвете и Экзодаре.', 24330),
(127073, 'ruRU', '', 'Мы не можем рисковать, позволив тебе устроить убийство в городе союзника, но никто не удивится, если ты уберёшь цель в Луносвете. Пока ты разбираешься с этой меткой, я отправлюсь в Экзодар.', 24330),
(127074, 'ruRU', '', 'Помни... хотя ты пытаешься им помочь, Орда решит, что ты напал на одного из своих.', 24330),
(127075, 'ruRU', '', 'Твоя первая метка выдаёт себя за богатого аристократа, разгуливающего по городу у всех на виду. Берегись его чародейского голема! Разлучи их, если сможешь... и действуй тихо.', 24330),
(127076, 'ruRU', '', 'Ах, чистый поворот ножа... восхитительно! Твоя следующая метка ждёт в Подгороде. Советую войти через канализацию с запада.', 24330),
(127077, 'ruRU', '', 'Твоя метка устраивает чаепитие на террасе над Кварталом разбойников. Будь осторожен! Её союзники - могущественные заклинатели, как и она сама. Тебе нужно найти способ попасть туда.', 24330),
(127078, 'ruRU', '', 'Этот предсмертный крик... чистая музыка! Мы обнаружили следующую метку в Громовом Утёсе, скрывающуюся в тени вождя тауренов.', 24330),
(127079, 'ruRU', '', 'Вот он, у костра. Слышала, он трус, уповающий на свои доспехи. Покажи ему, как он ошибается!', 24330),
(127080, 'ruRU', '', 'Мм, восхитительно... как нож во тьме! Твоя последняя метка будет найдена в Оргриммаре. Это будет самая сложная цель на данный момент!', 24330),
(127081, 'ruRU', '', 'Вот! В самом людном месте, какое можно представить - аукционном доме. Будь тих, бей точно и исчезай быстро!', 24330),
(127082, 'ruRU', '', 'Бедные, жалкие метки! Нет такого места, где бы тени не нашли их. Приходи, навести своих коллег. У лорда Равенхольда есть для тебя подарок.', 24330),
(127083, 'ruRU', '', 'Мы не можем рисковать, позволив тебе устроить убийство в городе союзника, но никто не удивится, если ты уберёшь цель в Экзодаре. Пока ты разбираешься с этой меткой, мы займёмся делом в Луносвете.', 24330),
(127084, 'ruRU', '', 'Помни... хотя ты пытаешься им помочь, Альянс решит, что ты напал на одного из своих.', 24330),
(127085, 'ruRU', '', 'Твоя первая метка носит облик смиренного священника, разгуливающего по городу у всех на виду. Берегись его кристального голема! Разлучи их, если сможешь... и действуй тихо.', 24330),
(127086, 'ruRU', '', 'Ах, чистый поворот ножа... восхитительно! Твоя следующая метка будет найдена в Дарнасе. Советую войти через деревню под Тельдрассилом.', 24330),
(127087, 'ruRU', '', 'Твоя метка устраивает приём в саду возле Террасы воинов. Будь осторожен! Её союзники - могущественные заклинатели, как и она сама. И берегись стражи.', 24330),
(127088, 'ruRU', '', 'Этот предсмертный крик... чистая музыка! Мы обнаружили следующую метку в Стальгорне, скрывающуюся в тени дворфийского совета.', 24330),
(127089, 'ruRU', '', 'Вот он, у стены. Слышала, он трус, уповающий на свои доспехи. Покажи ему, как он ошибается!', 24330),
(127090, 'ruRU', '', 'Мм, восхитительно... как нож во тьме! Твоя последняя метка будет найдена в Штормграде. Это будет самая сложная цель на данный момент!', 24330),
(127092, 'ruRU', '', 'Выше нос, Роланд. Похоже, помощь прибыла.', 24330),
(127097, 'ruRU', '', 'Ты сделал мудрый выбор. Вместе мы многого добьёмся.', 24330),
(127160, 'ruRU', '', 'Мы не можем позволить Пылающему Легиону добиться успеха.', 24330),
(127161, 'ruRU', '', 'Один был глупцом, выбрав тебя своим защитником.', 24330),
(127162, 'ruRU', '', 'Будет забавно увидеть его стыд, когда ты падёшь.', 24330),
(127163, 'ruRU', '', 'Таким, как ты, здесь не место. Эта земля НАША, и только мы достойны участвовать в этом турнире!', 24330),
(127164, 'ruRU', '', 'Интересно, будут ли помнить твоё имя после того, как ты провалишься...', 24330),
(127180, 'ruRU', '', 'Я... не могу продолжать...', 24330),
(127181, 'ruRU', '', 'Пожалуй... я просто... посижу чуток...', 24330),
(127182, 'ruRU', '', 'Джерод! Он... он мёртв. Нам нужно отступить, пока не прибудет подкрепление!', 24330),
(127183, 'ruRU', '', 'Не положено переживать своих внуков...', 24330),
(127184, 'ruRU', '', 'Взгляд %s стекленеет, а её ружьё падает на землю.', 24330),
(127185, 'ruRU', '', '%s падает на пол в отчаянии.', 24330),
(127186, 'ruRU', '', 'Вы слышали леди! Все на выход!', 24330),
(127188, 'ruRU', '', 'Готов ли ты ответить на зов славы, $c?', 24330),
(127190, 'ruRU', '', 'Есть опасность? Я справлюсь!', 24330),
(127191, 'ruRU', '', 'Как дела?', 24330),
(127192, 'ruRU', '', 'Почеши мне спину, а я поцарапаю твою.', 24330),
(127193, 'ruRU', '', 'Увидимся позже!', 24330);
